/**
 * Text — generated by the React Native Reusables CLI (`text`), re-skinned.
 *
 * Deviations from upstream, kept here so the next `add text --overwrite` diff reads:
 * - The base carries `font-sans` (Be Vietnam Pro) and `text-base` is 14px, the
 *   @chatofy/ui body size and React Native's own default — so swapping this in
 *   for `react-native`'s Text on an older screen changes the face and nothing else.
 * - Variants use only the token type scale: `h1` is the page title (`xl`, 28),
 *   `h2` a section heading (`lg`, 22), `h3` the translation size (`md`, 17).
 *   Weight stops at semibold; upstream's `font-extrabold` and `tracking-tight`
 *   have no token. `h2` drops upstream's rule underneath.
 * - `code` and `blockquote` are removed: no monospace face is loaded and nothing
 *   quotes. `p`, `lead` and `large` lose their `sm:` steps (no breakpoints here).
 */
import { cn } from '@/lib/utils';
import { Slot } from '@rn-primitives/slot';
import { cva, type VariantProps } from 'class-variance-authority';
import * as React from 'react';
import { Platform, Text as RNText, type Role } from 'react-native';

const textVariants = cva(
  cn('font-sans text-base text-foreground', Platform.select({ web: 'select-text' })),
  {
    variants: {
      variant: {
        default: '',
        h1: 'text-xl font-semibold',
        h2: 'text-lg font-semibold',
        h3: 'text-md font-semibold',
        h4: 'text-base font-semibold',
        p: 'mt-2 leading-6',
        lead: 'text-md text-muted-foreground',
        large: 'text-md font-semibold',
        small: 'text-sm font-medium',
        muted: 'text-sm text-muted-foreground',
      },
    },
    defaultVariants: {
      variant: 'default',
    },
  },
);

type TextVariantProps = VariantProps<typeof textVariants>;

type TextVariant = NonNullable<TextVariantProps['variant']>;

const ROLE: Partial<Record<TextVariant, Role>> = {
  h1: 'heading',
  h2: 'heading',
  h3: 'heading',
  h4: 'heading',
};

const ARIA_LEVEL: Partial<Record<TextVariant, string>> = {
  h1: '1',
  h2: '2',
  h3: '3',
  h4: '4',
};

const TextClassContext = React.createContext<string | undefined>(undefined);

function Text({
  className,
  asChild = false,
  variant = 'default',
  ...props
}: React.ComponentProps<typeof RNText> &
  React.RefAttributes<typeof RNText> &
  TextVariantProps & {
    asChild?: boolean;
  }) {
  const textClass = React.useContext(TextClassContext);
  const Component = asChild ? Slot : RNText;
  return (
    <Component
      className={cn(textVariants({ variant }), textClass, className)}
      role={variant ? ROLE[variant] : undefined}
      aria-level={variant ? ARIA_LEVEL[variant] : undefined}
      {...props}
    />
  );
}

export { Text, TextClassContext };
